@pytest.mark.parametrize("missing", [np.nan, pd.NA, None])
@pytest.mark.parametrize("values, expected", [
    ([1, 2, 3], "numeric"),
    ([True, False], "numeric"),
    (["1", "2"], "categorical"),
    ([1, "2"], "categorical"),
    ([pd.Timestamp(1), pd.Timestamp(2)], "datetime"),
    ([], "numeric"),
])
def test_variable_type_with_missing(values, expected, missing):

    s = pd.Series([*values, missing], dtype=object)
    assert variable_type(s) == expected
    assert variable_type(s.astype("category")) == "categorical"


