    ([], "numeric"),
])
def test_variable_type_with_missing(self, values, expected, missing):

    s = pd.Series([*values, missing], dtype=object)
    assert variable_type(s) == expected
    assert variable_type(s.to_numpy()) == expected
    assert variable_type(s.to_list()) == expected
    assert variable_type(s.astype("category")) == "categorical"

