@pytest.mark.parametrize("missing", [np.nan, pd.NA, None])
def test_map_numeric_with_missing(self, missing):

    data = pd.DataFrame({
        "date": ["0", "1", "2", "3"],
        "value": pd.Series([1, 2, 1, 1.5], dtype=object),
    })
    missing_data = data.copy()
    missing_data.loc[2, "value"] = missing
    data = pd.concat([
        data.assign(kind="complete"),
        missing_data.assign(kind="missing"),
    ])

    g = ag.FacetGrid(data, col="kind", sharey=False, sharex=True)
    g.map(lineplot, "date", "value")

    for ax in g.axes.flat:
        assert ax.get_ylim()[0] < ax.get_ylim()[1]
    complete_line = g.axes_dict["complete"].lines[0]
    assert_array_equal(complete_line.get_xdata(), [0, 1, 2, 3])
    assert_array_equal(complete_line.get_ydata(), [1, 2, 1, 1.5])
    missing_line = g.axes_dict["missing"].lines[0]
    assert_array_equal(missing_line.get_xdata(), [0, 1, 3])
    assert_array_equal(missing_line.get_ydata(), [1, 2, 1.5])

